import { createReadStream, createWriteStream } from 'node:fs';
import { pipeline } from 'node:stream/promises';
await pipeline(createReadStream('books.txt'), createWriteStream('copy.txt'));

import { EventEmitter } from 'node:events';
const library = new EventEmitter();
library.on('saved', title => console.log(title));
library.emit('saved', 'Dune');

import test from 'node:test';
import assert from 'node:assert/strict';
import { label } from './book.mjs';
test('formats a title', () => {
  assert.equal(label({ title: 'Dune' }), 'DUNE');
});

function titleOf(value) {
  if (typeof value !== 'string' || !value.trim()) throw new Error('Title required');
  return value.trim();
}

function titleOf(value: unknown): string {
  if (typeof value !== 'string' || !value.trim()) throw new Error('Title required');
  return value.trim();
}
